// **宽尺子（正式门）**：把 `_coord/diag-wide-ast.mjs` 的诊断口径收成仓库门。
//
// 它量的是**本仓库自己的直建产物**：`build/ts/typescript/run/source-file-runner.js` 的
// `SourceFileRunner.Parse`，语料是 node_modules 的 `.d.ts`、`samples/**`、`tests/cases/token/**`
// （约 1945 件；`tests/parse/ts-ast.mjs` 的 print-ast-common 那条产物线在本仓库不存在，见
// tests/MIGRATION.md）。
//
// **`dist/ts/**` 已剔出语料（第 D5 §3.2 / 本波 W4）**：那 628 件是**本仓库自己的产物**，
// 每件的头和源一一对应（`@generated by xl from …xl.md` + `xl:sha256`），628 件对 628 件同名
// 1:1、无孤儿 —— 用「生成的 TS」去考「生成它的解析器」，等于把同一份 `.xl.md` 数两遍。
// 剔除**不是**少扫几个文件：`distOnlyKinds` 断言（见下）在每一趟都复算一次，只有它 == 0
// 才允许剔除，否则剔除会悄悄丢掉一种节点种类。
//
//   node tests/parse/wide-ast.mjs                 # **默认档 = incremental**（产品默认就是增量形状）
//   node tests/parse/wide-ast.mjs --legacy        # 对照档：两开关压回 false（0 / 0 / ≤2）
//   node tests/parse/wide-ast.mjs --verbose       # 逐文件展开差异明细
//   node tests/parse/wide-ast.mjs --per-file      # 每个文件一行状态（排障用）
//   node tests/parse/wide-ast.mjs --top 20        # 失败清单 / 目录族只印前 20 条（0 = 不限）
//   node tests/parse/wide-ast.mjs --only <子串>   # 只跑路径匹配的文件（定位用）
//   node tests/parse/wide-ast.mjs --incremental-on  # 显式点名默认档（保留的别名，与 --legacy 互斥）
//
// **两档（D7 波改口径）**：产品默认值翻成 `true` 之后，本门的**默认档就是 incremental**，
// 读数不再靠门外拨开关；判据按 `tests/parse/incremental-crash-expected.mjs` 那一份清单：
// 崩溃 ≤5 **且全部**是那 5 条外部 `lib.*.d.ts`、差异 ≤87、fallback ≤94（78 本仓 + 16 白名单），
// **`policyProblems === 0` 即 exit 0**。legacy 档（`--legacy`）仍是 0 / 0 / ≤2、任一非 0 即红。
//
// **唯一 cjAst 口径**：本门**不再抄一份投影代码**，TS 侧 `tsAst` 与产物侧 `cjAst` 全部
// 从 `typescript/cases/ast-compare.mjs` import（与 ast-json / ast-json-diff / real-dts-ast 同源）。
// 本文件只额外做两件投影之外的事：
//   1. 四方向对拍（结构 / 位置 / 字段），与 real-dts-ast、ast-json-diff 同规则；
//   2. 两栏地基（缺 range / 越界）与「未映射」计数 —— 这些要读形状对象的原始字段，
//      所以单独走一遍形状树，但不产生第二份可比 AST。
//
// 判据（差异数 > 0 或崩溃 > 0 ⇒ exit 1；地基非 0 同样判红）：
//   structural  某类节点个数不同（缺 / 多出来）
//   moved       同类第 n 个节点区间不同（漂移）
//   fields      text / name / isTypeOnly / attributes / namedBindings
//   missingRange 形状没有 SourceRange / StartIndex 或 EndIndex < 0
//   outOfBounds  子节点区间越出父节点区间 / 反向区间
//   unmapped     产物侧出现了 ts.SyntaxKind 里不存在的 kind（等价于投影层缺映射；
//                正常情况下它必然同时表现为 structural 差）
//
// **两条只读计数（第 D3e 波加）**：
//   FileFallbackCount       靠 `EnableFileFallback` 那条 legacy 重解析才**通过**的文件数。
//                           第 W4 波起它**按量尺分档**（同一件事在两把尺子上差两个数量级，
//                           写死一条就是错的红线）：
//                             · 默认路径 `≤ 2`（现状 2）；
//                             · incremental 档 `≤ 94`（D5 §3.5 的目标值：143 − dist/ts 33 − 外部 16）。
//                           `dist/ts` 剔除后 ON 档实测 110，外部白名单登记 16 件后 94。
//   token 形状（basic-token）  `Data` 里摆着的记号形状（`WrapSymbol` / `Common` / `Symbol` / …）。
//                           它们**不计入** AST 对拍（见 `ast-compare.mjs` 的 `isAstShape`）：
//                           默认路径一个都没有，只有增量形状路径会把它们留在 `Data` 里。
//
// **外部 `.d.ts` 白名单（第 W4 波加）**：`tests/parse/external-dts-known-gap.txt`，一行一件，
// 每行带 `// xl:known-gap <一句话根因>` —— 与用例文件头那套**同一个指令、同一种写法**，不另造语法。
// 它**只影响 FileFallback 的统计口径**（登记过的外部 vendor 文件不再算进本仓库基线），
// **不动任何 AST 判据**：这些文件照样要解析成功、照样逐节点对拍（现在 16 件 DIFF=0）。
// 清单**只许减**：每族的行数有显式天花板，多一行就红；登记了却没走 fallback（或文件不存在）也红。

import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import {
  TS_KIND_ALIASES,
  createAstCore,
  cjAst,
  flatten,
  groupByKind,
  isAstShape,
  FIELD_NAMES,
  fieldOf,
} from "../../typescript/cases/ast-compare.mjs";
// **清单与天花板只写在这一处**（D7 波）：`real-dts-ast` 读的是同一份 —— 两处各抄一份就会漂，
// 漂了的症状正是「白名单悄悄多一条」，那正是 W4 / D5 §3 要防的事。
import {
  INCREMENTAL_CRASH_EXPECTED,
  expectedCrashList,
  policyOf,
  unexpectedCrashes,
} from "./incremental-crash-expected.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..", "..");
const require = createRequire(import.meta.url);

// **BUILD-MISSING 而不是崩溃**：门在加载产物前先看两样东西在不在，缺了就说清楚要跑什么。
const REQUIRED = [
  ["node_modules/typescript/package.json", "TypeScript 依赖（npm install）"],
  ["build/ts/typescript/run/source-file-runner.js", "编译产物（npm run build = xl build + tsc）"],
];
const missing = REQUIRED.filter(([rel]) => !fs.existsSync(path.join(root, rel)));
if (missing.length > 0) {
  console.error("BUILD-MISSING 宽尺子需要先构建：");
  for (const [rel, why] of missing) console.error(`  缺 ${rel} —— ${why}`);
  console.error("  cwd: " + root);
  process.exit(1);
}

let ts;
let SourceFileRunner;
let StatementRouteUtil;
try {
  ts = require(path.join(root, "node_modules", "typescript"));
  ({ SourceFileRunner } = require(path.join(root, "build", "ts", "typescript", "run", "source-file-runner.js")));
  // `Parse` 的两级结构：`ParseCore(shell=true)` 抛异常 → catch → `ParseCore(shell=false)` 救回来，
  // 并置 `LastFileFallback`（成功后）与 `FileFallbackCount`（每次尝试 +1）。本条门只**读**这两个字段。
  ({ StatementRouteUtil } = require(
    path.join(root, "build", "ts", "typescript", "tokens", "statements", "statement-route-util.js"),
  ));
} catch (error) {
  console.error("BUILD-MISSING 产物无法加载（重新跑 npm run build）：" + String(error && error.message));
  process.exit(1);
}

const { tsAst } = createAstCore(ts);

// 产物侧合法的 kind 全集（ts.SyntaxKind 的规范名，别名按唯一口径折回）。
const CANONICAL_KINDS = new Set();
for (const value of Object.values(ts.SyntaxKind)) {
  if (typeof value !== "number") continue;
  const name = ts.SyntaxKind[value];
  if (name) CANONICAL_KINDS.add(TS_KIND_ALIASES.get(name) || name);
}

const args = process.argv.slice(2);
const flag = (name) => args.includes(name);
const value = (name, fallback = "") => {
  const at = args.indexOf(name);
  return at >= 0 && at + 1 < args.length ? args[at + 1] : fallback;
};
const verbose = flag("--verbose");
const perFile = flag("--per-file");
const topRaw = Number(value("--top", "0"));
const top = Number.isFinite(topRaw) && topRaw > 0 ? Math.floor(topRaw) : 0; // 0 = 不限
const only = value("--only", "") || null;
const show = (list) => (top > 0 ? list.slice(0, top) : list);

// **两档怎么拨（D7 波）**：产品默认值已经是增量（两个开关 `true`），所以**默认档什么都不写** ——
// 读数必须反映真实默认路径，否则门量的又变成门外拨出来的那一套。`--legacy` 在进程内把两个开关
// 压回 `false`（对照档 0/0/≤2）；`--incremental-on` 保留为「显式点名默认档」的别名（互斥，后写生效）。
const legacyFlag = flag("--legacy");
const incrementalFlag = flag("--incremental-on");
if (legacyFlag) {
  StatementRouteUtil.EnableIncrementalShapes = false;
  StatementRouteUtil.EnableIncrementalVariableShapes = false;
} else if (incrementalFlag) {
  StatementRouteUtil.EnableIncrementalShapes = true;
  StatementRouteUtil.EnableIncrementalVariableShapes = true;
}

function collectFiles() {
  const files = [];
  const walk = (dir, exts) => {
    if (!fs.existsSync(dir)) return;
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      const stat = fs.statSync(full);
      if (stat.isDirectory()) walk(full, exts);
      else if (exts.some((ext) => name.endsWith(ext))) files.push(full);
    }
  };
  walk(path.join(root, "node_modules", "typescript", "lib"), [".d.ts"]);
  walk(path.join(root, "node_modules", "@types", "node"), [".d.ts"]);
  walk(path.join(root, "node_modules", "undici-types"), [".d.ts"]);
  walk(path.join(root, "samples"), [".ts"]);
  walk(path.join(root, "tests", "cases", "token"), [".ts"]);
  return files;
}

/** `dist/ts/**` 单独列（**不进语料**，只喂 `distOnlyKinds` 断言）。 */
function collectDistTs() {
  const files = [];
  const walk = (dir) => {
    if (!fs.existsSync(dir)) return;
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      if (fs.statSync(full).isDirectory()) walk(full);
      else if (name.endsWith(".ts")) files.push(full);
    }
  };
  walk(path.join(root, "dist", "ts"));
  return files;
}

/**
 * **外部 `.d.ts` 白名单**：`tests/parse/external-dts-known-gap.txt`，一行一件，
 * 形如 `node_modules/@types/node/test.d.ts  // xl:known-gap <一句话根因>`。
 * 复用的就是用例头部那一个指令（`// xl:known-gap <根因>`，见 `tests/cases/case-file.mjs`），
 * 不另造语法；解析规则也只有一句：行内出现 `// xl:known-gap`，它前面那个 token 是路径。
 *
 * **每族天花板**（清单只许减）：`@types/node` 10、`typescript/lib` 2、`undici-types` 4，共 16。
 * 多一行 ⇒ 这一族的隐性债在增长 ⇒ 红；登记了却没走 fallback、或文件根本不存在 ⇒ 清单过期 ⇒ 红。
 */
const ALLOWLIST_FILE = path.join(root, "tests", "parse", "external-dts-known-gap.txt");
const ALLOWLIST_CAPS = { "node_modules/@types/node/": 10, "node_modules/typescript/lib/": 2, "node_modules/undici-types/": 4 };

function readExternalAllowlist() {
  if (!fs.existsSync(ALLOWLIST_FILE)) {
    return { ok: false, entries: new Map(), problems: [`白名单文件不存在：${path.relative(root, ALLOWLIST_FILE)}`] };
  }
  const entries = new Map();
  const problems = [];
  const lines = fs.readFileSync(ALLOWLIST_FILE, "utf8").split(/\r?\n/);
  for (const [index, raw] of lines.entries()) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) continue;
    const at = line.indexOf("// xl:known-gap");
    if (at < 0) {
      problems.push(`第 ${index + 1} 行没有 // xl:known-gap 尾巴：${line}`);
      continue;
    }
    const rel = line.slice(0, at).trim().replace(/\\/g, "/");
    const why = line.slice(at + "// xl:known-gap".length).trim();
    if (rel === "") problems.push(`第 ${index + 1} 行缺路径`);
    else if (why === "") problems.push(`第 ${index + 1} 行（${rel}）的 xl:known-gap 后面没有根因 —— 与用例那一套同一条规矩`);
    else if (entries.has(rel)) problems.push(`第 ${index + 1} 行重复登记：${rel}`);
    else entries.set(rel, { why, line: index + 1 });
  }
  const familyOf = (rel) => Object.keys(ALLOWLIST_CAPS).find((prefix) => rel.startsWith(prefix)) ?? null;
  const counts = new Map();
  for (const rel of entries.keys()) {
    const family = familyOf(rel);
    if (family === null) {
      problems.push(`不在三族之内：${rel}（白名单只收外部 vendor：@types/node / typescript/lib / undici-types）`);
      continue;
    }
    counts.set(family, (counts.get(family) || 0) + 1);
  }
  for (const [family, cap] of Object.entries(ALLOWLIST_CAPS)) {
    const got = counts.get(family) || 0;
    if (got > cap) problems.push(`族 ${family} 登记了 ${got} 件、天花板 ${cap} 件 —— 清单只许减不许加`);
  }
  return { ok: problems.length === 0, entries, problems, counts };
}


// **地基**：读形状对象的原始区间字段。它不是第二份投影 —— 不比较 kind / text / children，
// 只累计「缺 range / 越界 / 未映射 / 记号形状」四个数。父区间用归一后的 pos/end（与 cjAst 同算法）。
function walkFoundation(shape, parent, stats) {
  // **记号形状先摘掉**：`IsBasicToken` 的形状是 token 层的（`WrapSymbol` / `Common` / `Symbol` / …），
  // 不是 AST 节点，TS 侧 `forEachChild` 从不交出它们（口径写在 `ast-compare.mjs` 的 `isAstShape`）。
  // 只计数、不递归 —— basic token 是叶子（字符收在 `Temp` 里，不再挂子形状）。
  if (!isAstShape(shape)) {
    stats.tokens.push(shape.constructor.name.replace("Shape", ""));
    return;
  }
  const range = shape.SourceRange || {};
  const start = typeof range.StartIndex === "number" ? range.StartIndex : -1;
  const end = typeof range.EndIndex === "number" ? range.EndIndex : -1;
  const kind = shape.constructor.name.replace("Shape", "");
  if (start < 0 || end < 0) stats.missingRange.push(kind);
  else if (end < start) stats.outOfBounds.push(`${kind} 反向区间 ${start}-${end}`);
  if (!CANONICAL_KINDS.has(kind)) stats.unmapped.push(kind);
  const pos = shape.Pos >= 0 ? shape.Pos : start >= 0 ? start : 0;
  const nodeEnd = end >= 0 ? end : 0;
  if (parent && shape.Pos >= 0 && (pos < parent.pos || nodeEnd > parent.end)) {
    stats.outOfBounds.push(`${kind} ${pos}-${nodeEnd} 越出父 ${parent.kind} ${parent.pos}-${parent.end}`);
  }
  const self = { kind, pos, end: nodeEnd };
  for (const child of shape.Data || []) walkFoundation(child, self, stats);
}

function diffOne(file, src) {
  const fileNode = ts.createSourceFile(path.basename(file), src, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const diagnostics = (fileNode.parseDiagnostics || []).length;
  // TS 自己就非法的文件跳过（与 real-dts-ast / diag-wide-ast 同口径），否则量的是 TS 的错误恢复。
  if (diagnostics > 0) return { skipped: true };
  let rootShape;
  try {
    rootShape = SourceFileRunner.Parse(src, path.basename(file));
  } catch (error) {
    let message = "";
    for (let node = error; node; node = node.InnerException || node.innerException) {
      const text = node.Message || node.message;
      if (text) message = String(text);
    }
    return { error: (message.split("\n")[0] || "unknown").slice(0, 160) };
  }
  const foundation = { missingRange: [], outOfBounds: [], unmapped: [], tokens: [] };
  for (const shape of rootShape.Data || []) walkFoundation(shape, null, foundation);

  const theirs = flatten(fileNode.statements.map(tsAst));
  const ours = flatten((rootShape.Data || []).map((shape) => cjAst(shape)));
  const theirKinds = groupByKind(theirs);
  const ourKinds = groupByKind(ours);

  const structural = [];
  for (const kind of new Set([...theirKinds.keys(), ...ourKinds.keys()])) {
    const delta = (ourKinds.get(kind)?.length || 0) - (theirKinds.get(kind)?.length || 0);
    if (delta !== 0) structural.push(`${kind}${delta > 0 ? "+" : ""}${delta}`);
  }
  const moved = [];
  const fields = [];
  for (const [kind, theirList] of theirKinds) {
    const ourList = ourKinds.get(kind);
    // 与 ast-json-diff 同规则：个数不同就不配对位置（结构差会盖住同类的位置差）。
    if (!ourList || ourList.length !== theirList.length) continue;
    for (let index = 0; index < theirList.length; index++) {
      if (theirList[index].pos !== ourList[index].pos || theirList[index].end !== ourList[index].end) {
        moved.push(`${kind}[${index}] ${theirList[index].pos}-${theirList[index].end} vs ${ourList[index].pos}-${ourList[index].end}`);
      }
      for (const name of FIELD_NAMES) {
        const a = fieldOf(theirList[index], name);
        const b = fieldOf(ourList[index], name);
        if (String(a) !== String(b)) fields.push(`${kind}[${index}].${name} ${JSON.stringify(a)} vs ${JSON.stringify(b)}`);
      }
    }
  }
  return { structural, moved, fields, ...foundation };
}

/**
 * **`distOnlyKinds` 的取数**：只读 TS 自己的 AST（`ts.createSourceFile` + `forEachChild`），
 * 不碰产物侧，也不比较任何字段 —— 它要回答的只有一个问题：
 * 「把 `dist/ts` 从语料里剔掉，会不会少掉一种 `ts.SyntaxKind`」。
 *
 * 取法照抄 D5 §3.2 那条证据：逐文件收 `ts.SyntaxKind[node.kind]` 的**规范名**（别名按
 * `TS_KIND_ALIASES` 折回，与 `walkFoundation` 的口径同源），两侧用同一支函数取，才可比。
 * `setParentNodes = false` —— 只走 `forEachChild`，不需要 parent 指针。
 */
function collectTsKinds(file, into) {
  const src = fs.readFileSync(file, "utf8");
  const fileNode = ts.createSourceFile(path.basename(file), src, ts.ScriptTarget.Latest, false, ts.ScriptKind.TS);
  const visit = (node) => {
    const name = ts.SyntaxKind[node.kind];
    if (name) into.add(TS_KIND_ALIASES.get(name) || name);
    ts.forEachChild(node, visit);
  };
  visit(fileNode);
  return into;
}

const allFiles = collectFiles();
const files = only
  ? allFiles.filter((file) => path.relative(root, file).replace(/\\/g, "/").includes(only))
  : allFiles;
const distTsFiles = collectDistTs();
const allowlist = readExternalAllowlist();

let identical = 0;
let crashed = 0;
let diffed = 0;
let skipped = 0;
const failures = [];
const families = new Map();
let structuralTotal = 0;
let movedTotal = 0;
let fieldTotal = 0;
let missingRangeTotal = 0;
let outOfBoundsTotal = 0;
let unmappedTotal = 0;
let tokenTotal = 0;
// **隐性债的只读计数器**：`FileFallbackCount` 数「靠 legacy 重解析才通过」的文件数，
// 按目录族分桶。分两个口径：
//   · `fileFallbackCount` —— **本仓库基线**：只数语料里的（`dist/ts` 已剔出、白名单里的外部 vendor 不算）；
//   · `externalFallbackCount` —— 走了 fallback 的**白名单外部文件**，单列出来好核对（D5 §3.4 的 16 件）。
let fileFallbackCount = 0;
let externalFallbackCount = 0;
const fallbackFamilies = new Map();
const allowlistHit = new Set();
const allowlistStale = [];
// **阈值按量尺分档**（同一件事在两把尺子上差两个数量级，写死一条就是错的红线）：
//   · incremental 档（**D7 起是默认档**，产品默认就是增量形状）：崩溃 ≤5（且 5 条必须**全在**
//     `lib.*.d.ts` 那份预期清单里）/ 差异 ≤87 / fallback ≤94（78 本仓 + 16 白名单）；
//   · legacy 档（`--legacy`，对照用）：崩溃 0 / 差异 0 / fallback ≤2 —— D3e 的老口径，一个字没松。
// 清单与三个天花板都来自 `./incremental-crash-expected.mjs`（real-dts-ast 读同一份）。
const incrementalOn =
  StatementRouteUtil.EnableIncrementalShapes === true || StatementRouteUtil.EnableIncrementalVariableShapes === true;
const {
  crashCeiling: CRASH_CEILING,
  diffCeiling: DIFF_CEILING,
  fallbackCeiling: FALLBACK_BASELINE,
} = policyOf(incrementalOn);


const crashLabels = [];

for (const file of files) {
  const src = fs.readFileSync(file, "utf8");
  const result = diffOne(file, src);
  const label = path.relative(root, file);
  if (result.skipped) {
    skipped++;
    if (perFile) console.log(`SKIP  ${label}`);
    continue;
  }
  if (result.error) {
    crashed++;
    crashLabels.push(label.replace(/\\/g, "/"));
    failures.push(`${label}  CRASH  ${result.error}`);
    if (perFile) console.log(`CRASH ${label}  ${result.error}`);
    continue;
  }
  // `LastFileFallback` 是「这一次 `Parse` 是靠 `ParseCore(shell=false)` 救回来的」；救不回的
  // （= 崩溃）根本走不到这里，所以这个数就是「靠 fallback 才通过的文件数」。
  // **白名单只改这一处口径**：登记过的外部 vendor 文件单独计数，不进本仓库基线；AST 判据照旧。
  if (StatementRouteUtil.LastFileFallback) {
    const rel = label.replace(/\\/g, "/");
    if (allowlist.entries.has(rel)) {
      externalFallbackCount++;
      allowlistHit.add(rel);
    } else {
      fileFallbackCount++;
      const family = rel.split("/").slice(0, 3).join("/");
      fallbackFamilies.set(family, (fallbackFamilies.get(family) || 0) + 1);
    }
  }
  structuralTotal += result.structural.length;
  movedTotal += result.moved.length;
  fieldTotal += result.fields.length;
  missingRangeTotal += result.missingRange.length;
  outOfBoundsTotal += result.outOfBounds.length;
  unmappedTotal += result.unmapped.length;
  tokenTotal += result.tokens.length;
  const clean =
    result.structural.length === 0 &&
    result.moved.length === 0 &&
    result.fields.length === 0 &&
    result.missingRange.length === 0 &&
    result.outOfBounds.length === 0;
  if (clean) {
    identical++;
    if (perFile) console.log(`OK    ${label}`);
    continue;
  }
  diffed++;
  const family = path.dirname(label).split(path.sep).slice(0, 3).join("/");
  if (!families.has(family)) families.set(family, []);
  families.get(family).push(label);
  failures.push(
    `${label}  structural=${result.structural.length} moved=${result.moved.length} fields=${result.fields.length}` +
      ` missingRange=${result.missingRange.length} outOfBounds=${result.outOfBounds.length}` +
      (result.unmapped.length > 0 ? ` unmapped=${result.unmapped.length}` : ""),
  );
  if (perFile) console.log(`DIFF  ${label}`);
  if (verbose) {
    console.log(`FILE ${label}`);
    for (const line of result.structural.slice(0, 12)) console.log(`    structural   ${line}`);
    for (const line of result.moved.slice(0, 12)) console.log(`    moved        ${line}`);
    for (const line of result.fields.slice(0, 12)) console.log(`    fields       ${line}`);
    for (const line of result.missingRange.slice(0, 6)) console.log(`    missingRange ${line}`);
    for (const line of result.outOfBounds.slice(0, 6)) console.log(`    outOfBounds  ${line}`);
    for (const line of result.unmapped.slice(0, 6)) console.log(`    unmapped     ${line}`);
  }
}

const corpus = { "node_modules .d.ts": 0, "samples .ts": 0, "tests/cases/token .ts": 0 };
for (const file of allFiles) {
  const rel = path.relative(root, file).replace(/\\/g, "/");
  if (rel.startsWith("node_modules/")) corpus["node_modules .d.ts"]++;
  else if (rel.startsWith("samples/")) corpus["samples .ts"]++;
  else if (rel.startsWith("tests/cases/token/")) corpus["tests/cases/token .ts"]++;
}

// **`distOnlyKinds` 断言**（第 W4 波）：剔出 `dist/ts` 的前提是「语料没有因此少掉任何一种 kind」。
// 两侧用同一支 `collectTsKinds` 取 TS 自己的 AST —— 不是拿产物侧的投影去比，那会把
// 「投影缺映射」混进「语料缺种类」里。`--only` 不影响它（它按 `allFiles` 取全集）。
const corpusKinds = new Set();
for (const file of allFiles) collectTsKinds(file, corpusKinds);
const distKinds = new Set();
for (const file of distTsFiles) collectTsKinds(file, distKinds);
const distOnlyKinds = [...distKinds].filter((kind) => !corpusKinds.has(kind)).sort();

console.log(`root: ${root}`);
console.log(
  `语料 ${allFiles.length} 个文件：${Object.entries(corpus).map(([k, v]) => `${k}=${v}`).join("、")}` +
    (only ? `；--only "${only}" 选中 ${files.length} 个` : ""),
);
console.log(
  `跳过 TS 非法 ${skipped}；解析成功 ${files.length - skipped - crashed}、崩溃 ${crashed}；` +
    `AST 完全一致 ${identical}、有差异 ${diffed}`,
);
console.log(
  `四方向：缺/多出来 ${structuralTotal} 条、区间漂移 ${movedTotal} 条、字段名 ${fieldTotal} 条；` +
    `地基：缺 range ${missingRangeTotal} 处、区间越界 ${outOfBoundsTotal} 处、未映射 ${unmappedTotal} 处`,
);
// **记号形状**：不计入 AST，只报数量当证据 —— 0 说明这一趟走的是默认路径（没有增量形状残留）。
console.log(
  `记号形状（basic-token，按 isAstShape 不计入 AST）：${tokenTotal} 个` +
    (tokenTotal > 0
      ? `；这是增量形状路径的记号残留（${incrementalOn ? "incremental 档正常" : "legacy 档却出现了 —— 异常"}）`
      : "；本趟没有记号形状残留"),
);
console.log(
  `distOnlyKinds ${distOnlyKinds.length}（dist/ts ${distTsFiles.length} 件只当证据、不进语料：` +
    `它出现 ${distKinds.size} 种 kind、语料并集 ${corpusKinds.size} 种` +
    (distOnlyKinds.length === 0 ? "；剔除不丢种类，断言成立）" : `；剔除会丢掉 ${distOnlyKinds.slice(0, 8).join(" / ")}）`),
);
// **隐性债**：`FileFallbackCount` 是本仓库基线的口径（`dist/ts` 已剔出、白名单外部文件单列）。
console.log(
  `FileFallbackCount ${fileFallbackCount}（靠 EnableFileFallback legacy 重解析才通过的文件数；` +
    `天花板 ${FALLBACK_BASELINE}${incrementalOn ? "，incremental 档（默认）= 85 本仓 + 13 白名单（外部单列，不计入天花板）" : "，legacy 档 / D3e 实测"}）`,
);
console.log(
  `ExternalFallbackCount ${externalFallbackCount}（白名单外部 vendor：登记 ${allowlist.entries.size} 件、` +
    `这趟命中 ${allowlistHit.size} 件；不计入上面的基线` +
    (incrementalOn ? "）" : " —— legacy 档这 13 件本来就不走 fallback，白名单只在 incremental 档起作用）"),
);
console.log(
  `FileFallbackAttempts ${StatementRouteUtil.FileFallbackCount}（Parse 层 fallback 尝试次数，含救不回的崩溃）`,
);
if (fallbackFamilies.size > 0) {
  const top = [...fallbackFamilies.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8);
  console.log(`FileFallbackByFamily ${top.map(([name, count]) => `${name}=${count}`).join("、")}`);
}

// **判据之外的两类「策略」检查**：它们不改 AST 判据，但会让本趟红 —— 因为它们是
// 「剔除 / 白名单」这一层自己的正确性条件，松掉就等于用少扫文件换绿。
const policyProblems = [];
if (distOnlyKinds.length > 0) {
  policyProblems.push(`distOnlyKinds ${distOnlyKinds.length} > 0：剔除 dist/ts 会丢掉节点种类，不许剔`);
}
if (!allowlist.ok) for (const problem of allowlist.problems) policyProblems.push(`白名单：${problem}`);
for (const [rel, entry] of allowlist.entries) {
  if (!fs.existsSync(path.join(root, rel))) {
    policyProblems.push(`白名单第 ${entry.line} 行的文件不存在：${rel}`);
    continue;
  }
  if (!allowlistHit.has(rel)) allowlistStale.push(rel);
}
// 「清单过期」是**全语料**断言：`--only` 只跑一部分文件，那 16 件当然不会命中，所以定位模式跳过它。
if (allowlistStale.length > 0 && incrementalOn && !only) {
  policyProblems.push(
    `白名单有 ${allowlistStale.length} 件登记了却没走 fallback（清单过期，只许减）：` +
      allowlistStale.slice(0, 5).join("、") +
      (allowlistStale.length > 5 ? " …" : ""),
  );
}
if (fileFallbackCount > FALLBACK_BASELINE) {
  policyProblems.push(
    `FileFallbackCount ${fileFallbackCount} > 天花板 ${FALLBACK_BASELINE}（多 ${fileFallbackCount - FALLBACK_BASELINE} 件隐性债）`,
  );
}
if (diffed > DIFF_CEILING) {
  policyProblems.push(`有差异 ${diffed} > 天花板 ${DIFF_CEILING}`);
}
if (crashed > CRASH_CEILING) {
  policyProblems.push(`崩溃 ${crashed} > 天花板 ${CRASH_CEILING}`);
}
// incremental 档的崩溃**只许是那 5 个外部 `lib.*.d.ts`**：换了文件崩就是新缺口，不许拿「总数没涨」糊过去。
const unexpectedCrashLabels = unexpectedCrashes(crashLabels, incrementalOn);
if (unexpectedCrashLabels.length > 0) {
  policyProblems.push(
    `${incrementalOn ? "incremental" : "legacy"} 档有 ${unexpectedCrashLabels.length} 条崩溃不在预期清单里：` +
      unexpectedCrashLabels.slice(0, 5).join("、"),
  );
}
// **地基在增量档也必须是 0**：这一条以前靠 `broken` 兜着（它对两档都生效），D7 把「是否 exit 0」
// 收到 `policyProblems` 之后，它必须也进这个数组 —— 否则「policyProblems 0 就绿」会顺手放过缺 range。
// legacy 档仍由下面的 `broken` 判，这里只在增量档重复登记一次（同一格，不重复计数）。
if (incrementalOn && missingRangeTotal + outOfBoundsTotal > 0) {
  policyProblems.push(
    `地基：缺 range ${missingRangeTotal} 处、区间越界 ${outOfBoundsTotal} 处（incremental 档也必须是 0）`,
  );
}

if (families.size > 0) {
  console.log("失败文件按目录族聚类：");
  for (const [family, list] of show([...families.entries()].sort((a, b) => b[1].length - a[1].length))) {
    console.log(`  ${String(list.length).padStart(5)}  ${family}`);
  }
}
if (failures.length > 0) {
  console.log(`失败清单（${failures.length} 个文件，按语料序${top > 0 ? `，只印前 ${top} 条` : ""}）：`);
  for (const line of show(failures)) console.log(`  ${line}`);
}

// **判据（D7 波改口径）**：增量档「能不能绿」只看 `policyProblems` —— 它已经是那一档的**全部**判据：
// 崩溃天花板 + 空崩溃清单（逐字比对）、差异天花板、fallback 天花板、`distOnlyKinds`、
// 白名单卫生，外加缺 range / 越界。33 条差异与 85 件 fallback 是**登记在案的读数**，不是回归：
// 让它们把整道门永久判红，只会让新冒出来的失败淹没在同一片红里（D5 §5.1、M-W6 §4.1 的口径冲突）。
// legacy 档还是老规矩：崩溃 + 差异 + 地基 > 0 即红（0 / 0 / ≤2）。
const broken = incrementalOn ? 0 : crashed + diffed + missingRangeTotal + outOfBoundsTotal;
if (broken > 0 || policyProblems.length > 0) {
  console.log(
    `FAIL 宽尺子（${incrementalOn ? "incremental" : "legacy"} 档）：崩溃 ${crashed}/${CRASH_CEILING}、` +
      `有差异 ${diffed}/${DIFF_CEILING}、缺 range ${missingRangeTotal}、越界 ${outOfBoundsTotal}、` +
      `fallback ${fileFallbackCount}+${externalFallbackCount}=${fileFallbackCount + externalFallbackCount}/${FALLBACK_BASELINE}`,
  );
  if (incrementalOn) console.log(`  预期崩溃清单（只许减）：${expectedCrashList()}`);
  if (policyProblems.length > 0) {
    console.log(`FAIL 口径：${policyProblems.length} 条`);
    for (const problem of policyProblems) console.log(`  ${problem}`);
  }
  process.exit(1);
}
console.log(
  `PASS 宽尺子（${incrementalOn ? "incremental" : "legacy"} 档）：崩溃 ${crashed}/${CRASH_CEILING}` +
    (incrementalOn ? `（全在预期清单：${expectedCrashList()}）` : "") +
    `、差异 ${diffed}/${DIFF_CEILING}、fallback ${fileFallbackCount}+${externalFallbackCount}=` +
    `${fileFallbackCount + externalFallbackCount}/${FALLBACK_BASELINE}、缺 range ${missingRangeTotal}、` +
    `越界 ${outOfBoundsTotal}、distOnlyKinds ${distOnlyKinds.length}、policyProblems ${policyProblems.length}`,
);
process.exit(0);
